#define main historical_main
#include "../cooling-cuda/main.cu"
#undef main
#include <vector>
#include <algorithm>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;const int num=512;std::vector<double>temp(num),cpu[2];for(int i=0;i<num;i++)temp[i]=pow(10.,3.+5.*i/(num-1));double *dt,*dr[2];CK(cudaMalloc(&dt,num*sizeof(double)));CK(cudaMemcpy(dt,temp.data(),num*sizeof(double),cudaMemcpyHostToDevice));for(int heat=0;heat<=1;heat++){cpu[heat].resize(num);reference(num,.0899,temp.data(),cpu[heat].data(),heat);CK(cudaMalloc(&dr[heat],num*sizeof(double)));cool_kernel<<<2,256>>>(num,.0899,dt,dr[heat],heat);}CK(cudaDeviceSynchronize());bool allok=true;
for(int trial=1;trial<=5;trial++){std::vector<double>out(2*num);double seconds=0,ma=0,mr=0;bool ok=true;for(int heat=0;heat<=1;heat++){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)cool_kernel<<<2,256>>>(num,.0899,dt,dr[heat],heat);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;CK(cudaMemcpy(out.data()+heat*num,dr[heat],num*sizeof(double),cudaMemcpyDeviceToHost));for(int i=0;i<num;i++){double got=out[heat*num+i],expected=cpu[heat][i],err=fabs(got-expected);ma=fmax(ma,err);mr=fmax(mr,err/fmax(fabs(expected),1e-300));ok&=std::isfinite(got)&&std::isfinite(expected)&&err<=1e-34+1e-10*fabs(expected);}}allok&=ok;char file[80];sprintf(file,"cooling_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(double),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":1024,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_full_primordial_cooling_heat0_heat1_transfer_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":1024,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",ma,mr,repeat,file);}for(auto d:dr)CK(cudaFree(d));CK(cudaFree(dt));puts(allok?"PASS":"FAIL");return allok?0:1;}
